"""T-001: generate configuration-record.md from the sealed stores and the replay summary (no transcription)."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[5]
HERE = Path(__file__).resolve().parent
ST = ROOT / 'exploration/aries_integrated/studies'
FS = json.loads((ST / '20260925-aries-flow-scaling-check/results/cases.json').read_text())['cases']
NET = json.loads((ST / '20260925-aries-revised-reference-network/results/cases.json').read_text())['cases']
rows = {r['case']: r for r in NET}; rows.update({r['case']: r for r in FS})
CAN, CTL, BASE = 'resized-compressor-1700-network-scaledflows-0.85', 'resized-compressor-1700-network-0.85', 'nominal-calculated'
c, k, b = rows[CAN], rows[CTL], rows[BASE]
replay = json.loads((HERE / 'replay-alternative.json').read_text())
integ = json.loads((ROOT / 'work/orchestration/goals/aries-reference-heat-electricity-reconciliation/evidence/integration-attempt2/integration_return.json').read_text())
manifest = json.loads((ST / 'manifest.json').read_text())
P = 'aries_integrated_plant__'
def o(row, name): return row['outputs'].get(P + name)
def i(row, name): return row['inputs'].get(P + name)
def f(v, nd=6):
    if v is None: return '—'
    return f'{v:.{nd}f}' if isinstance(v, float) and abs(v) < 1e15 else str(v)
L = []
L.append('# Configuration record — the 891 MW modeled alternative (T-001, generated from the sealed stores)\n')
L.append('[AGENT] Generated by `configuration-record.py` on 2026-09-25 from `results/cases.json` of the two sealed studies and from `replay-alternative.json`; nothing is transcribed by hand. The alternative is a modeled alternative, not the ARIES reference and not an upper bound (owner ruling 2026-09-25). Values are native stored outputs; MW unless stated; money USD2004.\n')
L.append('## 1. Identity\n')
L.append('| Item | Value |\n|---|---|')
L.append(f"| Package | `{replay['package']}` |")
L.append(f"| Executable fingerprint (sealed = replay) | `{c['executable_fingerprint']}` |")
L.append(f"| Semantic fingerprint (live manifest) | `{manifest['fingerprints']['recorded_provenance']['semantic_fingerprint']}` |")
tc = integ.get('toolchain', {}); L.append(f"| TEAx revision (integration CANDIDATE toolchain) | `{tc.get('teax_revision') or tc.get('revision') or json.dumps(tc)[:200]}` |")
L.append(f"| Canonical case | `{CAN}` from `20260925-aries-flow-scaling-check@77098a41`, candidate `{c['candidate_id']}`; replay candidate `{replay['cases'][CAN]['replay_candidate_id']}`; {replay['cases'][CAN]['channels_compared']} channels at zero deviation, verdicts identical |")
L.append(f"| Unscaled-mapping control | `{CTL}` from the same record (verbatim control of the round-2 case, `20260925-aries-revised-reference-network@352ecee4`), candidate `{k['candidate_id']}`; replay exact |")
L.append(f"| Assumed 423 MW baseline | `{BASE}` from `20260925-aries-revised-reference-network@352ecee4`, candidate `{b['candidate_id']}`; replay exact |")
L.append(f"| Replay tolerances | declared in `replay-tolerance-declaration.md` before the run; result `all_passed = {replay['passed']}` |\n")
L.append('## 2. Full input map of the canonical case\n')
L.append('Every entry key of the package (the complete map is also stored verbatim in the sealed `cases.json` and in the replay store). Keys are shown without the `aries_integrated_plant__` prefix; plasma keys keep theirs. The 22 keys that differ from the 423 MW baseline are marked **changed** with the baseline value; the two keys that differ from the unscaled control are marked *mapping*.\n')
L.append('| Key | Canonical value | Baseline value | Note |\n|---|---:|---:|---|')
for key in sorted(c['inputs']):
    v, bv, kv = c['inputs'][key], b['inputs'].get(key), k['inputs'].get(key)
    note = []
    if v != bv: note.append('**changed**')
    if v != kv: note.append('*mapping*')
    bvs = repr(bv) if v != bv else ''
    L.append(f"| `{key.replace(P, '')}` | {v!r} | {bvs} | {' '.join(note)} |")
L.append('')
L.append('## 3. Selected equipment (supplied choices) and their purchases\n')
L.append('| Item | Selected key | Canonical | Baseline | Purchase output | Canonical USD2004 | Baseline USD2004 | Quantity ratio |\n|---|---|---:|---:|---|---:|---:|---:|')
sel = [('Compressor rating MW', 'compressor_capacity__selected_rating', 'compressor_equipment__purchase__capital', 'compressor_equipment__purchase__quantity_ratio'),
       ('Turbine rating MW', 'turbine_capacity__selected_rating', 'turbine_equipment__purchase__capital', 'turbine_equipment__purchase__quantity_ratio'),
       ('Generator rating MW', 'generator_capacity__selected_rating', 'generator_equipment__purchase__capital', 'generator_equipment__purchase__quantity_ratio'),
       ('Heat rejection rating MW', 'rejection_capacity__selected_rating', 'heat_rejection_equipment__purchase__capital', 'heat_rejection_equipment__purchase__quantity_ratio'),
       ('He duty package MW', 'he_capacity__selected_rating', 'he_duty_equipment__purchase__capital', 'he_duty_equipment__purchase__quantity_ratio'),
       ('PbLi duty package MW', 'pbli_capacity__selected_rating', 'pbli_duty_equipment__purchase__capital', 'pbli_duty_equipment__purchase__quantity_ratio'),
       ('Divertor duty package MW', 'divertor_capacity__selected_rating', 'divertor_duty_equipment__purchase__capital', 'divertor_duty_equipment__purchase__quantity_ratio'),
       ('Fuel processing rating atoms/s', 'fuel_capacity__selected_rating', 'fuel_processing_equipment__purchase__capital', 'fuel_processing_equipment__purchase__quantity_ratio'),
       ('He pump capacity kg/s', 'he_pump__selected_flow_capacity', 'he_pump__purchase__capital', 'he_pump__purchase__quantity_ratio'),
       ('PbLi pump capacity kg/s', 'pbli_pump__selected_flow_capacity', 'pbli_pump__purchase__capital', 'pbli_pump__purchase__quantity_ratio'),
       ('Divertor pump capacity kg/s', 'divertor_pump__selected_flow_capacity', 'divertor_pump__purchase__capital', 'divertor_pump__purchase__quantity_ratio'),
       ('He exchanger area m²', 'he_hx__selected_area', 'he_hx__purchase__capital', 'he_hx__purchase__quantity_ratio'),
       ('PbLi exchanger area m²', 'pbli_hx__selected_area', 'pbli_hx__purchase__capital', 'pbli_hx__purchase__quantity_ratio'),
       ('Divertor exchanger area m²', 'divertor_hx__selected_area', 'divertor_hx__purchase__capital', 'divertor_hx__purchase__quantity_ratio'),
       ('Selected T stock kg', 'fuel_inventory__selected_tritium_kg', 'fuel_inventory__purchase__amount', None)]
for label, key, pur, ratio in sel:
    L.append(f"| {label} | `{key}` | {i(c, key)!r} | {i(b, key)!r} | `{pur}` | {f(o(c, pur), 2)} | {f(o(b, pur), 2)} | {f(o(c, ratio), 6) if ratio else '—'} |")
L.append('')
L.append('Fixed one-package allowances (no selected quantity): ' + ', '.join(f"`{n}` {f(o(c, n + '__purchase__cost'), 0)}" for n in ('conversion_services', 'secondary_transport', 'primary_piping', 'electrical_equipment', 'facilities', 'heating_equipment', 'magnet_power_supplies', 'instrumentation_control', 'other_reactor_equipment', 'miscellaneous_equipment', 'auxiliary_cooling', 'waste_equipment', 'impurity_control', 'site_land', 'vf_coils', 'divertor_inventory', 'fuel_services', 'unallocated_source_scope')) + '. Cycle flow (`cycle__selected_flow` 1700 kg/s), recuperator effectiveness (`cycle__recuperator_effectiveness` 0.95), network mode and split are operating or assumed choices bound to no purchase.\n')
L.append('## 4. Operating demands against the supplied ratings (the 14 evaluated checks)\n')
L.append('| Check (`source_local_identity`) | Demand output | Demand | Supplied rating or capacity | Margin output | Margin | Verdict |\n|---|---|---:|---:|---|---:|---|')
chk = [('compressor_capacity', 'plant_ledger__evaluate__compressor_demand', 'compressor_capacity__selected_rating', 'compressor_capacity__evaluate__margin'),
       ('turbine_capacity', 'turbine__evaluate__shaft_produced', 'turbine_capacity__selected_rating', 'turbine_capacity__evaluate__margin'),
       ('generator_capacity', 'plant_ledger__evaluate__gross_electric', 'generator_capacity__selected_rating', 'generator_capacity__evaluate__margin'),
       ('rejection_capacity', 'plant_ledger__evaluate__cycle_rejection', 'rejection_capacity__selected_rating', 'rejection_capacity__evaluate__margin'),
       ('he_capacity', 'he_coolant__evaluate__delivered_heat', 'he_capacity__selected_rating', 'he_capacity__evaluate__margin'),
       ('pbli_capacity', 'pbli_coolant__evaluate__delivered_heat', 'pbli_capacity__selected_rating', 'pbli_capacity__evaluate__margin'),
       ('divertor_capacity', 'divertor_coolant__evaluate__delivered_heat', 'divertor_capacity__selected_rating', 'divertor_capacity__evaluate__margin'),
       ('fuel_capacity', 'fuel__evaluate__exhaust_rate', 'fuel_capacity__selected_rating', 'fuel_capacity__evaluate__margin'),
       ('he_pump', 'heat_exchangers__he_flow', 'he_pump__selected_flow_capacity', 'he_pump__screen__margin'),
       ('pbli_pump', 'heat_exchangers__pbli_flow', 'pbli_pump__selected_flow_capacity', 'pbli_pump__screen__margin'),
       ('divertor_pump', 'heat_exchangers__divertor_flow', 'divertor_pump__selected_flow_capacity', 'divertor_pump__screen__margin'),
       ('fuel_inventory', 'fuel_inventory__annual__required_stock', 'fuel_inventory__selected_tritium_kg', 'fuel_inventory__screen__margin')]
verd = {cid.split('__')[1]: st for cid, st in c['verdicts'].items()}
for name, dem, rat, mar in chk:
    d = o(c, dem) if o(c, dem) is not None else i(c, dem)
    L.append(f"| `{name}/capacity_ok` | `{dem}` | {f(d, 3)} | {i(c, rat)!r} | `{mar}` | {f(o(c, mar), 3)} | {verd.get(name)} |")
L.append(f"| `plant_ledger/heat_removal_ok` | `heat_exchangers__evaluate__unmet_heat` | {f(o(c, 'heat_exchangers__evaluate__unmet_heat'), 6)} | 0 (all heat removed) | — | — | {verd.get('plant_ledger') if False else c['verdicts'].get(next(x for x in c['verdicts'] if 'heat_removal_ok' in x))} |")
L.append(f"| `plant_ledger/balances_ok` | `plant_ledger__evaluate__residual_magnitude` | {f(o(c, 'plant_ledger__evaluate__residual_magnitude'), 9)} | ledger tolerance | — | — | {c['verdicts'].get(next(x for x in c['verdicts'] if 'balances_ok' in x))} |")
L.append('\nRating is purchased capacity; demand is the calculated operating quantity; a margin below zero is reported as a violated check, never resized away.\n')
L.append('## 5. Heat balance and electricity\n')
L.append('| Quantity | Output | Canonical | Unscaled control | Baseline 423 MW |\n|---|---|---:|---:|---:|')
hb = [('Fusion power supplied (mode 0)', 'source__evaluate__selected_power'), ('He circuit delivered heat', 'he_coolant__evaluate__delivered_heat'), ('PbLi delivered heat', 'pbli_coolant__evaluate__delivered_heat'), ('Divertor delivered heat', 'divertor_coolant__evaluate__delivered_heat'),
      ('Total available heat', 'plant_ledger__evaluate__total_available_heat'), ('Accepted by the cycle', 'heat_exchangers__evaluate__accepted_heat'), ('Unmet heat (He / PbLi / div)', 'heat_exchangers__evaluate__unmet_heat'), ('He stage unmet', 'heat_exchangers__evaluate__he_unmet'), ('PbLi stage unmet', 'heat_exchangers__evaluate__pbli_unmet'), ('Divertor stage unmet', 'heat_exchangers__evaluate__divertor_unmet'),
      ('Heater inlet K', 'heat_exchangers__evaluate__heater_inlet'), ('Turbine inlet K', 'heat_exchangers__evaluate__turbine_temperature'), ('Thermal efficiency', 'plant_ledger__evaluate__thermal_efficiency'), ('Turbine shaft', 'turbine__evaluate__shaft_produced'), ('Compressor demand (three stages)', 'plant_ledger__evaluate__compressor_demand'), ('Gross electric', 'plant_ledger__evaluate__gross_electric'),
      ('He pump electric', 'he_pump__evaluate__electric'), ('PbLi pump electric', 'pbli_pump__evaluate__electric'), ('Divertor pump electric', 'divertor_pump__evaluate__electric'), ('Auxiliary electric (total)', 'plant_ledger__evaluate__auxiliary_electric'), ('Net electric', 'plant_ledger__evaluate__net_electric'), ('Cycle rejection', 'plant_ledger__evaluate__cycle_rejection'), ('Ledger residual magnitude', 'plant_ledger__evaluate__residual_magnitude')]
for label, key in hb:
    L.append(f"| {label} | `{key}` | {f(o(c, key))} | {f(o(k, key))} | {f(o(b, key))} |")
L.append('')
L.append('## 6. Economic entry state (no-breeding-credit inputs, default finance; to be audited, not yet assessed)\n')
L.append('| Quantity | Output | Canonical | Unscaled control | Baseline 423 MW |\n|---|---|---:|---:|---:|')
ec = [('Direct capital', 'cost_ledger__evaluate__direct'), ('Overnight capital', 'cost_ledger__evaluate__overnight'), ('Construction financing (midpoint IDC)', 'lifecycle_accounts__evaluate__idc'), ('Financed capital', 'lifecycle_accounts__evaluate__financed_capital'),
      ('Annual operating cost', 'cost_ledger__evaluate__annual_operating'), ('Fixed annual O&M', 'annual_om__evaluate__annual_om'), ('External tritium purchase cost per year', 'fuel_inventory__annual__annual_cost'), ('Deuterium per year', 'fuel_inventory__deuterium__annual_fuel'),
      ('T burn kg/yr', 'fuel_inventory__annual__annual_burn'), ('T permanent loss kg/yr', 'fuel_inventory__annual__annual_loss'), ('T stock decay kg/yr', 'fuel_inventory__annual__annual_decay'), ('Gross T makeup kg/yr', 'lifecycle_accounts__evaluate__gross_makeup'), ('External T purchases kg/yr', 'lifecycle_accounts__evaluate__external_shortfall'),
      ('Replacement event cost', 'replacement__evaluate__event_cost'), ('Replacement events', 'replacement__evaluate__event_count'), ('Undiscounted replacements', 'replacement__evaluate__lifetime_total'), ('PV replacements', 'lifecycle_accounts__evaluate__pv_replacement'), ('Other overhaul (year 20)', 'lifecycle_accounts__evaluate__other_overhaul_cost'), ('Gross terminal', 'lifecycle_accounts__evaluate__gross_terminal'), ('Salvage', 'lifecycle_accounts__evaluate__salvage'),
      ('Annual energy MWh', 'lifecycle_accounts__evaluate__annual_energy'), ('PV energy MWh', 'lifecycle_accounts__evaluate__pv_energy'), ('PV total cost', 'lifecycle_accounts__evaluate__pv_total_cost'),
      ('LCOE capital', 'lifecycle_accounts__evaluate__capital_lcoe'), ('LCOE O&M', 'lifecycle_accounts__evaluate__om_lcoe'), ('LCOE tritium', 'lifecycle_accounts__evaluate__tritium_lcoe'), ('LCOE supply service', 'lifecycle_accounts__evaluate__supply_lcoe'), ('LCOE deuterium', 'lifecycle_accounts__evaluate__deuterium_lcoe'), ('LCOE consumables', 'lifecycle_accounts__evaluate__consumables_lcoe'), ('LCOE replacements', 'lifecycle_accounts__evaluate__replacement_lcoe'), ('LCOE overhaul', 'lifecycle_accounts__evaluate__other_overhaul_lcoe'), ('LCOE terminal', 'lifecycle_accounts__evaluate__terminal_lcoe'), ('LCOE salvage', 'lifecycle_accounts__evaluate__salvage_lcoe'), ('LCOE imports', 'lifecycle_accounts__evaluate__imports_lcoe'), ('LCOE total', 'lifecycle_price__evaluate__lcoe'),
      ('Source-conditioned diagnostic LCOE (supplied 1000 MW, 5,055.77 MUSD)', 'source_lifecycle_price__evaluate__lcoe')]
for label, key in ec:
    L.append(f"| {label} | `{key}` | {f(o(c, key), 6)} | {f(o(k, key), 6)} | {f(o(b, key), 6)} |")
L.append('\nScientific support flags (`plant_ledger__evaluate__supported_*`): ' + ', '.join(f"{n} = {o(c, 'plant_ledger__evaluate__supported_' + n)}" for n in ('magnet', 'breeding', 'deposition', 'hydraulics', 'materials', 'machine_map')) + '. A finite LCOE upgrades none of them.\n')
(HERE / 'configuration-record.md').write_text('\n'.join(L) + '\n')
print('rows', len(c['inputs']), 'outputs', len(c['outputs']), 'verdicts', len(c['verdicts']))
